<?php
require_once __DIR__ . '/../includes/auth.php'; require_role(['teacher']); require __DIR__ . '/../config/database.php'; $pageTitle='Activities'; $q=$pdo->prepare('SELECT a.title,a.activity_type,a.due_at,s.subject_name FROM activities a JOIN subjects s ON s.id=a.subject_id WHERE a.created_by=? ORDER BY a.created_at DESC');$q->execute([$_SESSION['user_id']]);$rows=$q->fetchAll();require __DIR__ . '/../includes/header.php'; ?>
<section class="panel"><div class="panel-head"><h3>Assignments and quizzes</h3></div><?php if(!$rows): ?><p class="empty">No activities created yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Activity</th><th>Subject</th><th>Type</th><th>Due date</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['subject_name']) ?></td><td><?= e(ucfirst($r['activity_type'])) ?></td><td><?= e($r['due_at'] ?: 'No deadline') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p class="muted section-gap">Activity creation form is planned for the next development phase.</p></section>
